BEGIN;

CREATE FUNCTION pg_temp.expect_failure(test_name TEXT, statement TEXT, expected_message TEXT) RETURNS VOID LANGUAGE plpgsql AS $$
DECLARE actual_message TEXT;
BEGIN
    BEGIN EXECUTE statement;
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS actual_message = MESSAGE_TEXT;
        IF strpos(actual_message, expected_message) > 0 THEN RAISE NOTICE 'PASS: %', test_name; RETURN; END IF;
        RAISE EXCEPTION 'FAIL: % returned unexpected error: %', test_name, actual_message;
    END;
    RAISE EXCEPTION 'FAIL: % unexpectedly succeeded', test_name;
END;
$$;

INSERT INTO "persona_profiles" ("id", "silo_id", "user_id", "updated_at") VALUES ('preference-profile','silo-preference','user-1',clock_timestamp());
INSERT INTO "preference_facts" ("id", "silo_id", "user_id", "persona_profile_id", "preference_key", "statement", "state", "consent_state", "provenance_kind", "provenance", "confidence", "sensitivity", "recorded_by", "idempotency_key") VALUES ('preference-candidate','silo-preference','user-1','preference-profile','answer.tone','Use a calm tone.','candidate','pending','explicit_statement','{"source":"user"}',1,'ordinary','user-1','preference-candidate');
SELECT pg_temp.expect_failure('candidate cannot forge acceptance evidence while forgotten', $statement$UPDATE "preference_facts" SET "state" = 'forgotten', "consent_state" = 'confirmed', "accepted_by" = 'user-1', "accepted_at" = clock_timestamp(), "forgotten_at" = clock_timestamp() WHERE "id" = 'preference-candidate'$statement$, 'forgotten PreferenceFact must retain only prior acceptance evidence');
UPDATE "preference_facts" SET "state" = 'accepted', "consent_state" = 'confirmed', "accepted_by" = 'user-1', "accepted_at" = clock_timestamp() WHERE "id" = 'preference-candidate';
SELECT pg_temp.expect_failure('promoted candidate acceptance remains immutable', $statement$UPDATE "preference_facts" SET "accepted_at" = clock_timestamp() WHERE "id" = 'preference-candidate'$statement$, 'PreferenceFact acceptance evidence is immutable');
